async function saveUD(uid,d){try{await setDoc(doc(db,"users",uid),d,{merge:true});}catch(e){console.error("Save:",e);}}
async function loadUD(uid){try{const s=await getDoc(doc(db,"users",uid));return s.exists()?s.data():null;}catch(e){return null;}}
function AuthScreen(){const[isL,setIsL]=useState(true);const[em,setEm]=useState("");const[pw,setPw]=useState("");const[nm,setNm]=useState("");const[err,setErr]=useState("");const[ld,setLd]=useState(false);const go=async()=>{setErr("");setLd(true);try{if(isL){await signInWithEmailAndPassword(auth,em,pw);}else{const c=await createUserWithEmailAndPassword(auth,em,pw);if(nm.trim())await updateProfile(c.user,{displayName:nm.trim()});await saveUD(c.user.uid,{coins:0,upgrades:{maxHP:0,baseDmg:0,critRate:0},completed:[],wrongAnswers:[],unlockedUnits:["infantry"],displayName:nm.trim()||"Commander"});}}catch(e){setErr(e.code==="auth/email-already-in-use"?"Email taken":e.code==="auth/invalid-credential"?"Wrong credentials":e.code==="auth/weak-password"?"6+ chars":e.message);}setLd(false);};const iS={width:"100%",padding:"12px 16px",borderRadius:8,border:"1px solid rgba(255,255,255,0.15)",background:"rgba(20,18,14,0.8)",color:"#E0E0E0",fontFamily:fonts.body,fontSize:"0.95rem",outline:"none"};return(<div style={{display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",minHeight:"100vh",gap:20,padding:24,backgroundColor:"#1a1510",backgroundImage:"url(/bg/leather-tile.jpg)",backgroundSize:"512px 512px",backgroundRepeat:"repeat",position:"relative"}}><div style={{position:"absolute",inset:0,background:"radial-gradient(ellipse at 50% 30%, rgba(40,30,15,0.3) 0%, transparent 70%)"}}/><div style={{position:"relative",zIndex:1,display:"flex",flexDirection:"column",alignItems:"center",gap:20}}><img src="/logo.png" alt="History Legends" style={{width:180,height:"auto",filter:"drop-shadow(0 4px 15px rgba(255,215,0,0.2))"}}/><div style={{fontFamily:fonts.body,color:"#999"}}>{isL?"Sign in":"Create account"}</div><div style={{width:"100%",maxWidth:340,display:"flex",flexDirection:"column",gap:12}}>{!isL&&<input placeholder="Commander Name" value={nm} onChange={e=>setNm(e.target.value)} style={iS}/>}<input type="email" placeholder="Email" value={em} onChange={e=>setEm(e.target.value)} style={iS}/><input type="password" placeholder="Password" value={pw} onChange={e=>setPw(e.target.value)} style={iS} onKeyDown={e=>e.key==="Enter"&&go()}/>{err&&<div style={{fontFamily:fonts.body,fontSize:"0.8rem",color:"#EF5350",textAlign:"center"}}>{err}</div>}<button onClick={go} disabled={ld} style={{...goldBtn,width:"100%",padding:"14px",opacity:ld?0.6:1}}>{ld?"...":(isL?"Sign In":"Create Account")}</button><button onClick={()=>{setIsL(!isL);setErr("");}} style={{background:"none",border:"none",color:"#4FC3F7",fontFamily:fonts.body,fontSize:"0.85rem",cursor:"pointer",padding:8}}>{isL?"Sign up":"Sign in"}</button></div></div></div>);}

