function ShopScreen({onBack,coins,upgrades,onBuy}){return(<div style={{padding:20,animation:"fadeIn 0.4s ease-out"}}><BB onClick={onBack}/><div style={{textAlign:"center",marginBottom:20}}><div style={{fontFamily:fonts.heading,fontSize:"1.4rem",fontWeight:700,color:"#FFD700"}}>Upgrade Shop</div><div style={{fontFamily:fonts.mono,fontSize:"1rem",color:"#FFD700",marginTop:6}}>🪙 {coins}</div></div><div style={{display:"flex",flexDirection:"column",gap:12,maxWidth:400,margin:"0 auto"}}>{["maxHP","baseDmg","critRate"].map(k=>{const u=UPGRADES[k],lv=upgrades[k],mx=lv>=u.levels.length-1,nc=mx?0:u.costs[lv+1],ca=coins>=nc;return(<div key={k} style={{background:"rgba(20,18,14,0.8)",border:"1px solid rgba(255,255,255,0.1)",borderRadius:12,padding:"14px 16px",boxShadow:"0 2px 6px rgba(0,0,0,0.25)"}}><div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:6}}><div style={{display:"flex",alignItems:"center",gap:8}}><span style={{fontSize:"1.1rem"}}>{u.icon}</span><span style={{fontFamily:fonts.heading,fontSize:"0.75rem",fontWeight:700,color:"#E0E0E0"}}>{u.label}</span></div><span style={{fontFamily:fonts.mono,fontSize:"0.65rem",color:"#888"}}>Lv {lv+1}/{u.levels.length}</span></div><div style={{display:"flex",gap:3,marginBottom:8}}>{u.levels.map((_,i)=>(<div key={i} style={{flex:1,height:3,borderRadius:2,background:i<=lv?"#4FC3F7":"rgba(255,255,255,0.08)"}}/>))}</div><div style={{display:"flex",justifyContent:"space-between",alignItems:"center"}}><span style={{fontFamily:fonts.mono,fontSize:"0.7rem",color:"#4FC3F7"}}>{u.desc[lv]}{!mx&&` → ${u.desc[lv+1]}`}</span>{mx?<span style={{fontFamily:fonts.heading,fontSize:"0.55rem",color:"#81C784"}}>MAX</span>:<button onClick={()=>ca&&onBuy(k)} style={{...btn(ca?"linear-gradient(135deg,#FFD700,#FFA000)":"rgba(255,255,255,0.05)",ca?"transparent":"rgba(255,255,255,0.1)"),padding:"5px 14px",fontSize:"0.6rem",color:ca?"#1a1a2e":"#666",fontWeight:700,cursor:ca?"pointer":"default",opacity:ca?1:0.5}}>🪙 {nc}</button>}</div></div>);})}</div></div>);}

function UnitSelectScreen({battle,era,unlockedUnits,coins,onUnlock,onGo,onBack}){
  const[squad,setSquad]=useState([]);
  const uName=(u)=>u.eraNames?.[era]||u.name;
  const addUnit=u=>{if(squad.length<3)setSquad([...squad,u]);};
  const removeUnit=i=>setSquad(squad.filter((_,j)=>j!==i));
  return(<div style={{padding:20,animation:"fadeIn 0.4s ease-out"}}><BB onClick={onBack}/>
    <div style={{textAlign:"center",marginBottom:12}}><div style={{fontFamily:fonts.heading,fontSize:"0.55rem",letterSpacing:"0.2em",color:"#4FC3F7",textTransform:"uppercase"}}>Build Your Squad</div><div style={{fontFamily:fonts.heading,fontSize:"1.1rem",fontWeight:700,color:"#E0E0E0",marginTop:4}}>{battle.name}</div></div>
    {/* Current squad */}
    <div style={{display:"flex",justifyContent:"center",gap:10,marginBottom:16}}>
      {[0,1,2].map(i=>(
        <div key={i} onClick={()=>squad[i]&&removeUnit(i)} style={{width:70,height:80,borderRadius:10,border:`2px dashed ${squad[i]?"rgba(79,195,247,0.5)":"rgba(255,255,255,0.15)"}`,background:squad[i]?"rgba(20,30,40,0.8)":"rgba(20,18,14,0.6)",display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",cursor:squad[i]?"pointer":"default",transition:"all 0.2s",boxShadow:"0 2px 6px rgba(0,0,0,0.3)"}}>
          {squad[i]?<><span style={{fontSize:"1.4rem"}}>{squad[i].icon}</span><span style={{fontFamily:fonts.heading,fontSize:"0.45rem",color:squad[i].color,marginTop:2}}>{uName(squad[i])}</span></>:<span style={{fontFamily:fonts.mono,fontSize:"0.6rem",color:"#666"}}>{i+1}</span>}
        </div>
      ))}
    </div>
    <div style={{textAlign:"center",marginBottom:12}}><span style={{fontFamily:fonts.mono,fontSize:"0.7rem",color:squad.length===3?"#81C784":"#aaa"}}>{squad.length}/3 selected</span></div>
    {/* Enemy preview */}
    <div style={{background:"rgba(40,15,15,0.8)",border:"1px solid rgba(211,47,47,0.25)",borderRadius:10,padding:"8px 14px",marginBottom:14,maxWidth:400,margin:"0 auto 14px",boxShadow:"0 2px 8px rgba(0,0,0,0.3)"}}><div style={{fontFamily:fonts.heading,fontSize:"0.45rem",letterSpacing:"0.12em",color:"#FF5252",textTransform:"uppercase",marginBottom:4}}>Enemy Forces</div><div style={{display:"flex",gap:8,justifyContent:"center"}}>{battle.enemies.map((e,i)=>(<div key={i} style={{textAlign:"center"}}><span style={{fontSize:"1rem"}}>{e.icon}</span><div style={{fontFamily:fonts.mono,fontSize:"0.5rem",color:"#EF5350"}}>{e.name}</div><div style={{fontFamily:fonts.mono,fontSize:"0.45rem",color:"#aaa"}}>HP:{e.hp} DMG:{e.dmg}</div></div>))}</div></div>
    {/* Unit roster */}
    <div style={{display:"flex",flexDirection:"column",gap:8,maxWidth:400,margin:"0 auto"}}>
      {UNITS.map(u=>{const owned=unlockedUnits.includes(u.id);const canBuy=coins>=u.cost;
        return(<button key={u.id} onClick={()=>owned?addUnit(u):canBuy&&onUnlock(u)} disabled={(!owned&&!canBuy)||squad.length>=3} style={{background:owned?"rgba(20,25,30,0.8)":"rgba(20,18,14,0.7)",border:`1px solid ${owned?"rgba(79,195,247,0.25)":"rgba(255,255,255,0.1)"}`,borderRadius:10,padding:"10px 14px",textAlign:"left",cursor:(owned||canBuy)&&squad.length<3?"pointer":"default",opacity:(!owned&&!canBuy)||squad.length>=3?0.35:1,width:"100%",transition:"all 0.2s",boxShadow:"0 2px 6px rgba(0,0,0,0.25)"}}>
          <div style={{display:"flex",justifyContent:"space-between",alignItems:"center"}}>
            <div style={{display:"flex",alignItems:"center",gap:8}}><span style={{fontSize:"1.1rem"}}>{u.icon}</span><div><div style={{fontFamily:fonts.heading,fontSize:"0.7rem",fontWeight:700,color:u.color}}>{uName(u)}</div><div style={{fontFamily:fonts.body,fontSize:"0.7rem",color:"#aaa"}}>{u.desc}</div></div></div>
            {!owned&&<span style={{fontFamily:fonts.mono,fontSize:"0.7rem",color:canBuy?"#FFD700":"#666"}}>🪙 {u.cost}</span>}
            {owned&&<span style={{fontFamily:fonts.mono,fontSize:"0.55rem",color:u.color}}>HP×{u.hpMult} DMG×{u.dmgMult}</span>}
          </div>
        </button>);
      })}
    </div>
    {squad.length===3&&<div style={{textAlign:"center",marginTop:16}}><button onClick={()=>onGo(squad)} style={{...goldBtn,padding:"14px 48px",fontSize:"0.9rem"}}>⚔️ Deploy Squad</button></div>}
  </div>);
}

const SPRITE_DATA=[{name:"Colonial Minuteman",prefix:"colonial",era:"Revolutionary War",color:"#4FC3F7"},{name:"British Redcoat",prefix:"british",era:"Revolutionary War",color:"#EF5350"},{name:"Confederate Soldier",prefix:"confederate",era:"Civil War",color:"#CE93D8"},{name:"Union GI",prefix:"gi",era:"Civil War",color:"#66BB6A"},{name:"Doughboy",prefix:"doughboy",era:"World War I",color:"#EF9A9A"},{name:"Imperial German",prefix:"imperial",era:"World War I",color:"#FFB74D"},{name:"American GI",prefix:"gi",era:"World War II",color:"#81C784"},{name:"German Soldier",prefix:"german",era:"World War II",color:"#EF5350"},{name:"Activist",prefix:"activist",era:"Civil Rights",color:"#FFB74D"},{name:"Police",prefix:"police",era:"Civil Rights",color:"#90CAF9"},{name:"Soviet Agent",prefix:"soviet",era:"Cold War",color:"#EF5350"},{name:"CIA Agent",prefix:"agent",era:"Cold War",color:"#90CAF9"},{name:"Cowboy",prefix:"cowboy",era:"Westward Expansion",color:"#FFCC80"},{name:"Bison",prefix:"bison",era:"Westward Expansion",color:"#A1887F"}];
function SpriteGalleryScreen({onBack}){const[sel,setSel]=useState(null);const poses=["idle","attack","hit","critical"];return(<div style={{padding:20,animation:"fadeIn 0.4s ease-out"}}><BB onClick={onBack}/><div style={{textAlign:"center",marginBottom:24}}><div style={{fontFamily:fonts.heading,fontSize:"1.5rem",fontWeight:700,color:"#FFD700"}}>Sprite Gallery</div><div style={{fontFamily:fonts.body,fontSize:"0.85rem",color:"#888",marginTop:4}}>All character art</div></div>{sel===null?<div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(140px,1fr))",gap:12,maxWidth:600,margin:"0 auto"}}>{SPRITE_DATA.map((s,i)=>(<div key={i} onClick={()=>setSel(i)} style={{background:"rgba(20,18,14,0.8)",border:"1px solid rgba(255,255,255,0.1)",borderRadius:12,padding:12,cursor:"pointer",textAlign:"center"}}><img src={"/sprites/"+s.prefix+"-idle.png"} alt={s.name} style={{width:80,height:80,objectFit:"contain"}}/><div style={{fontFamily:fonts.heading,fontSize:"0.7rem",color:s.color,marginTop:6}}>{s.name}</div><div style={{fontFamily:fonts.body,fontSize:"0.6rem",color:"#666"}}>{s.era}</div></div>))}</div>:<div style={{maxWidth:400,margin:"0 auto"}}><button onClick={()=>setSel(null)} style={{background:"none",border:"none",color:"#4FC3F7",fontFamily:fonts.body,fontSize:"0.85rem",cursor:"pointer",marginBottom:16}}>Back to Gallery</button><div style={{textAlign:"center",marginBottom:16}}><div style={{fontFamily:fonts.heading,fontSize:"1.2rem",color:SPRITE_DATA[sel].color}}>{SPRITE_DATA[sel].name}</div><div style={{fontFamily:fonts.body,fontSize:"0.8rem",color:"#888"}}>{SPRITE_DATA[sel].era}</div></div><div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:12}}>{poses.map(p=>(<div key={p} style={{background:"rgba(20,18,14,0.8)",border:"1px solid rgba(255,255,255,0.1)",borderRadius:12,padding:16,textAlign:"center"}}><img src={"/sprites/"+SPRITE_DATA[sel].prefix+"-"+p+".png"} alt={p} style={{width:100,height:100,objectFit:"contain"}}/><div style={{fontFamily:fonts.mono,fontSize:"0.7rem",color:"#999",marginTop:6,textTransform:"capitalize"}}>{p}</div></div>))}</div></div>}</div>);}

function HomeScreen({onNav,coins,userName,onLogout}){return(<div style={{display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",minHeight:"80vh",gap:20,padding:20}}><img src="/logo.png" alt="History Legends" style={{width:220,height:"auto",filter:"drop-shadow(0 4px 15px rgba(255,215,0,0.2))"}}/><div style={{fontFamily:fonts.heading,fontSize:"0.5rem",letterSpacing:"0.25em",color:"#9a8a6a",textTransform:"uppercase",marginTop:-10}}>Learn History Through Battle</div><div style={{fontFamily:fonts.body,color:"#9E9E9E"}}>Welcome, <span style={{color:"#4FC3F7"}}>{userName}</span></div><div style={{display:"flex",alignItems:"center",gap:12}}><div style={{background:"rgba(20,18,14,0.8)",border:"1px solid rgba(255,215,0,0.2)",borderRadius:10,padding:"10px 24px",display:"flex",alignItems:"center",gap:10,boxShadow:"0 2px 8px rgba(0,0,0,0.3)"}}><span style={{fontSize:"1.2rem"}}>🪙</span><span style={{fontFamily:fonts.mono,fontSize:"1.3rem",color:"#FFD700",fontWeight:700}}>{coins}</span></div></div><div style={{width:"100%",maxWidth:380,display:"flex",flexDirection:"column",gap:10}}><MC onClick={()=>onNav(SCREENS.US_HISTORY)}><span style={{fontSize:"1.5rem"}}>🇺🇸</span><div><div style={{fontFamily:fonts.heading,fontSize:"0.85rem",fontWeight:700,color:"#4FC3F7"}}>US HISTORY</div><div style={{fontFamily:fonts.body,fontSize:"0.8rem",color:"#888",marginTop:2}}>Rev War · Civil War · WWII · Civil Rights · WWI · Cold War · Westward</div></div></MC><MC onClick={()=>onNav(SCREENS.SPRITE_GALLERY)}><span style={{fontSize:"1.5rem"}}>🎨</span><div><div style={{fontFamily:fonts.heading,fontSize:"0.85rem",fontWeight:700,color:"#FFD700"}}>SPRITE GALLERY</div><div style={{fontFamily:fonts.body,fontSize:"0.8rem",color:"#888",marginTop:2}}>View all character art</div></div></MC><MC disabled accent="#666"><span style={{fontSize:"1.5rem"}}>🏰</span><div><div style={{fontFamily:fonts.heading,fontSize:"0.85rem",color:"#666"}}>EUROPEAN — Coming soon</div></div></MC></div><button onClick={onLogout} style={{background:"none",border:"none",fontFamily:fonts.body,fontSize:"0.8rem",color:"#666",cursor:"pointer",padding:8,marginTop:8}}>Sign Out</button></div>);}
function USScreen({onNav,onBack,completed}){const prog=(battles)=>{const c=battles.filter(b=>(completed||[]).includes(b.id)).length;return c+"/"+battles.length;};return(<div style={{padding:20,animation:"fadeIn 0.4s ease-out"}}><BB onClick={onBack}/><div style={{textAlign:"center",marginBottom:24}}><div style={{fontFamily:fonts.heading,fontSize:"1.5rem",fontWeight:700,color:"#E0E0E0"}}>US History</div></div><div style={{display:"flex",flexDirection:"column",gap:10,maxWidth:400,margin:"0 auto"}}><MC onClick={()=>onNav(SCREENS.REV_WAR)}><span style={{fontSize:"1.4rem"}}>⚔️</span><div><div style={{fontFamily:fonts.heading,fontSize:"0.85rem",fontWeight:700,color:"#4FC3F7"}}>REVOLUTIONARY WAR</div><div style={{fontFamily:fonts.body,fontSize:"0.8rem",color:"#888",marginTop:2}}>{prog(BATTLES)} · 13 Battles</div></div></MC><MC onClick={()=>onNav(SCREENS.WW2)}><span style={{fontSize:"1.4rem"}}>🪖</span><div><div style={{fontFamily:fonts.heading,fontSize:"0.85rem",fontWeight:700,color:"#81C784"}}>WORLD WAR II</div><div style={{fontFamily:fonts.body,fontSize:"0.8rem",color:"#888",marginTop:2}}>{prog(WW2_BATTLES)} · 6 Battles</div></div></MC><MC onClick={()=>onNav(SCREENS.CIVIL_WAR)}><span style={{fontSize:"1.4rem"}}>🦅</span><div><div style={{fontFamily:fonts.heading,fontSize:"0.85rem",fontWeight:700,color:"#CE93D8"}}>CIVIL WAR</div><div style={{fontFamily:fonts.body,fontSize:"0.8rem",color:"#888",marginTop:2}}>{prog(CW_BATTLES)} · 7 Battles</div></div></MC><MC onClick={()=>onNav(SCREENS.CIVIL_RIGHTS)}><span style={{fontSize:"1.4rem"}}>✊</span><div><div style={{fontFamily:fonts.heading,fontSize:"0.85rem",fontWeight:700,color:"#FFB74D"}}>CIVIL RIGHTS</div><div style={{fontFamily:fonts.body,fontSize:"0.8rem",color:"#888",marginTop:2}}>{prog(CR_BATTLES)} · 5 Milestones</div></div></MC><MC onClick={()=>onNav(SCREENS.WWI)}><span style={{fontSize:"1.4rem"}}>💣</span><div><div style={{fontFamily:fonts.heading,fontSize:"0.85rem",fontWeight:700,color:"#EF9A9A"}}>WORLD WAR I</div><div style={{fontFamily:fonts.body,fontSize:"0.8rem",color:"#888",marginTop:2}}>{prog(WWI_BATTLES)} · 3 Battles</div></div></MC><MC onClick={()=>onNav(SCREENS.COLD_WAR)}><span style={{fontSize:"1.4rem"}}>☢️</span><div><div style={{fontFamily:fonts.heading,fontSize:"0.85rem",fontWeight:700,color:"#90CAF9"}}>COLD WAR</div><div style={{fontFamily:fonts.body,fontSize:"0.8rem",color:"#888",marginTop:2}}>{prog(CW2_BATTLES)} · 2 Crises</div></div></MC><MC onClick={()=>onNav(SCREENS.WESTWARD)}><span style={{fontSize:"1.4rem"}}>🤠</span><div><div style={{fontFamily:fonts.heading,fontSize:"0.85rem",fontWeight:700,color:"#FFCC80"}}>WESTWARD EXPANSION</div><div style={{fontFamily:fonts.body,fontSize:"0.8rem",color:"#888",marginTop:2}}>{prog(WE_BATTLES)} · 4 Events</div></div></MC></div></div>);}

function MapDoodles({width,height}){
  // Generate scattered terrain doodles
  const trees=[];const rocks=[];const mountains=[];
  const rng=(s)=>{let x=Math.sin(s)*10000;return x-Math.floor(x);};
  for(let i=0;i<40;i++){
    const x=rng(i*7.3)*width;const y=rng(i*13.1)*height;
    if(rng(i*3.7)>0.5)trees.push({x,y,s:4+rng(i*2.1)*6});
    else rocks.push({x,y,s:3+rng(i*4.9)*5});
  }
  for(let i=0;i<8;i++){mountains.push({x:rng(i*9.7)*width,y:rng(i*5.3)*height*0.3,s:12+rng(i*6.1)*10});}
  return(<g opacity="0.18" strokeLinecap="round" strokeLinejoin="round">
    {trees.map((t,i)=><g key={`t${i}`} transform={`translate(${t.x},${t.y})`}><polygon points={`0,${-t.s} ${-t.s*0.6},${t.s*0.3} ${t.s*0.6},${t.s*0.3}`} fill="#5a4a2a" stroke="#4a3a1a" strokeWidth="0.8"/><rect x={-0.8} y={t.s*0.3} width={1.6} height={t.s*0.4} fill="#6a4a2a"/></g>)}
    {rocks.map((r,i)=><g key={`r${i}`} transform={`translate(${r.x},${r.y})`}><ellipse rx={r.s} ry={r.s*0.6} fill="none" stroke="#7a6a4a" strokeWidth="0.8"/><line x1={-r.s*0.3} y1={-r.s*0.2} x2={r.s*0.2} y2={r.s*0.1} stroke="#7a6a4a" strokeWidth="0.5"/></g>)}
    {mountains.map((m,i)=><g key={`m${i}`} transform={`translate(${m.x},${m.y})`}><path d={`M${-m.s},${m.s*0.6} L${-m.s*0.3},${-m.s*0.4} L${m.s*0.1},${-m.s*0.1} L${m.s*0.5},${-m.s*0.5} L${m.s},${m.s*0.6}Z`} fill="none" stroke="#6a5a3a" strokeWidth="1"/><line x1={m.s*0.5} y1={-m.s*0.5} x2={m.s*0.3} y2={-m.s*0.2} stroke="#6a5a3a" strokeWidth="0.6"/></g>)}
    {/* Scattered dots and hash marks for terrain texture */}
    {Array.from({length:25},(_,i)=>{const x=rng(i*11.3+50)*width;const y=rng(i*8.7+50)*height;return<circle key={`d${i}`} cx={x} cy={y} r={1} fill="#7a6a4a"/>;})}
  </g>);
}
function MapScreen({onBack,onSelect,completed,mapData,battles,title}){const sR=useRef(null);useEffect(()=>{if(sR.current)sR.current.scrollTop=sR.current.scrollHeight;},[]);const m=mapData,ns=90,mh=m.length*ns+120,pw=340;const gX=i=>{const c=(m.length-1-i)%6;return[0.5,0.28,0.5,0.72,0.5,0.32][c];};const pts=m.map((_,i)=>({x:gX(i)*pw,y:55+i*ns}));
  const segments=pts.map((p,i)=>{if(i===0)return null;const pr=pts[i-1];return`M ${pr.x} ${pr.y} C ${pr.x} ${(pr.y+p.y)/2}, ${p.x} ${(pr.y+p.y)/2}, ${p.x} ${p.y}`;}).filter(Boolean);
  const done=battles.filter(b=>completed.includes(b.id)).length;
  return(<div style={{height:"100vh",display:"flex",flexDirection:"column",animation:"fadeIn 0.4s ease-out",background:"#2a2118"}}>
    <div style={{padding:"10px 20px 8px",flexShrink:0,background:"linear-gradient(180deg,#3b2f22,#2a2118)",borderBottom:"2px solid #5a4a35",zIndex:5}}>
      <BB onClick={onBack}/>
      <div style={{textAlign:"center"}}><div style={{fontFamily:fonts.heading,fontSize:"1.15rem",fontWeight:700,color:"#D4B87A",textShadow:"0 1px 3px rgba(0,0,0,0.5)"}}>{title}</div><div style={{fontFamily:fonts.mono,fontSize:"0.5rem",color:"#8a7a60",marginTop:2}}>{done}/{battles.length} complete</div></div>
    </div>
    <div ref={sR} style={{flex:1,overflowY:"auto",overflowX:"hidden",position:"relative"}}>
      <svg style={{position:"sticky",top:0,width:"100%",height:16,zIndex:4,display:"block"}} viewBox="0 0 400 16" preserveAspectRatio="none"><path d="M0,0 L400,0 L400,6 L390,9 L375,5 L360,10 L345,7 L330,11 L315,6 L300,9 L285,5 L270,10 L255,7 L240,11 L225,6 L210,9 L195,5 L180,10 L165,7 L150,11 L135,6 L120,9 L105,5 L90,10 L75,7 L60,11 L45,6 L30,9 L15,5 L0,8Z" fill="#C4A462"/></svg>
      <div style={{backgroundImage:"url(/bg/map-parchment.jpg)",backgroundSize:"100% auto",backgroundRepeat:"repeat-y",backgroundPosition:"top center",backgroundColor:"#C4A462",position:"relative",minHeight:mh+20}}>
        <div style={{position:"absolute",inset:0,background:"rgba(30,20,10,0.12)",pointerEvents:"none"}}/>
        <div style={{position:"absolute",top:6,left:10,right:10,bottom:6,border:"2.5px solid rgba(90,65,25,0.3)",borderRadius:3,pointerEvents:"none"}}/>
        <div style={{position:"absolute",top:12,left:16,right:16,bottom:12,border:"1px solid rgba(90,65,25,0.18)",borderRadius:2,pointerEvents:"none"}}/>
        <div style={{position:"relative",width:"100%",maxWidth:pw,margin:"0 auto",height:mh,padding:"0 10px"}}>
          <svg style={{position:"absolute",top:0,left:0,width:pw,height:mh,pointerEvents:"none"}} viewBox={`0 0 ${pw} ${mh}`}>
            <MapDoodles width={pw} height={mh}/>
            {segments.map((d,i)=><g key={`seg${i}`}><path d={d} fill="none" stroke="rgba(90,60,20,0.2)" strokeWidth="24" strokeLinecap="round"/><path d={d} fill="none" stroke="#5a3a1a" strokeWidth="2.5" strokeLinecap="round" strokeDasharray="6 8" opacity="0.6"/></g>)}
            <g transform={`translate(${pw-35},40)`} opacity="0.2"><circle cx="0" cy="0" r="16" fill="none" stroke="#5a3a1a" strokeWidth="1"/><circle cx="0" cy="0" r="2" fill="#5a3a1a"/><line x1="0" y1="-16" x2="0" y2="16" stroke="#5a3a1a" strokeWidth="0.7"/><line x1="-16" y1="0" x2="16" y2="0" stroke="#5a3a1a" strokeWidth="0.7"/><polygon points="0,-14 -3,-5 3,-5" fill="#5a3a1a"/><text x="0" y="-17" textAnchor="middle" fontSize="6" fill="#5a3a1a" fontFamily="serif" fontWeight="bold">N</text></g>
          </svg>
          <div style={{position:"absolute",top:10,left:"50%",transform:"translateX(-50%)",fontFamily:fonts.heading,fontSize:"0.5rem",letterSpacing:"0.2em",color:"#6B4F2A",opacity:0.4,whiteSpace:"nowrap"}}>🏆 Victory 🏆</div>
          <div style={{position:"absolute",bottom:12,left:"50%",transform:"translateX(-50%)",fontFamily:fonts.heading,fontSize:"0.5rem",letterSpacing:"0.2em",color:"#7B5A30"}}>▼ Start Here ▼</div>
          {m.map((b,i)=>{const pt=pts[i];const bc=battles.find(x=>x.id===b.id);const ic=completed.includes(b.id);const bi=battles.findIndex(x=>x.id===b.id);const av=bi===0||(bi>0&&completed.includes(battles[bi-1].id));const iB=!!b.boss;const iF=b.boss==="FINAL BOSS";const sz=iF?62:iB?52:44;const nc=ic?"#4a7a2e":av?"#8B5E3C":iF?"#8B6914":iB?"#A0522D":"#8a7a66";
            return(<div key={b.id+i} style={{position:"absolute",top:pt.y-sz/2,left:pt.x,transform:"translateX(-50%)",display:"flex",flexDirection:"column",alignItems:"center",cursor:(av||ic)&&bc?"pointer":"default",zIndex:av?3:1}} onClick={()=>(av||ic)&&bc&&onSelect(bc)}>
              {iB&&<div style={{fontFamily:fonts.heading,fontSize:"0.42rem",letterSpacing:"0.12em",color:iF?"#7B5518":"#8B4513",textTransform:"uppercase",marginBottom:2,textShadow:"0 1px 1px rgba(255,230,150,0.4)"}}>{b.boss}</div>}
              <div style={{width:sz,height:sz,borderRadius:"50%",background:ic?"rgba(74,122,46,0.4)":av?"rgba(180,140,80,0.45)":"rgba(100,80,60,0.25)",border:`3px solid ${ic?"#4a7a2e":av?"#8B6B3E":"#9a8a7066"}`,display:"flex",alignItems:"center",justifyContent:"center",position:"relative",boxShadow:av||ic?"0 3px 12px rgba(0,0,0,0.4), inset 0 1px 3px rgba(255,255,255,0.2)":"inset 0 1px 2px rgba(0,0,0,0.2)",backdropFilter:"blur(2px)"}}>{av&&!ic&&<div style={{position:"absolute",inset:-6,borderRadius:"50%",border:"2px solid rgba(139,107,62,0.5)",animation:"pulse 2s infinite"}}/>}<span style={{fontSize:iF?"1.4rem":iB?"1.2rem":"1rem",filter:!av&&!ic?"grayscale(1) opacity(0.35)":"none"}}>{ic?"⭐":av?b.icon:"🔒"}</span></div>
              <div style={{textAlign:"center",marginTop:4,maxWidth:120,background:"rgba(30,20,10,0.5)",borderRadius:6,padding:"2px 8px"}}><div style={{fontFamily:fonts.heading,fontSize:"0.55rem",fontWeight:700,color:ic?"#8BC34A":av?"#D4B87A":"#9a8a70",lineHeight:1.2,textShadow:"0 1px 2px rgba(0,0,0,0.6)"}}>{b.name}</div><div style={{fontFamily:fonts.mono,fontSize:"0.42rem",color:ic?"#7aa03a":"#8a7a60",marginTop:1}}>{b.date}</div></div>
            </div>);})}
        </div>
      </div>
      <svg style={{width:"100%",height:16,display:"block",marginTop:-1}} viewBox="0 0 400 16" preserveAspectRatio="none"><path d="M0,16 L400,16 L400,10 L390,7 L375,11 L360,6 L345,9 L330,5 L315,10 L300,7 L285,11 L270,6 L255,9 L240,5 L225,10 L210,7 L195,11 L180,6 L165,9 L150,5 L135,10 L120,7 L105,11 L90,6 L75,9 L60,5 L45,10 L30,7 L15,11 L0,8Z" fill="#C4A462"/></svg>
    </div>
  </div>);}

function PreBattle({battle,era,onStart,onBack,difficulty,onDiffChange}){const eraLabels={"revwar":"Revolutionary War","ww2":"World War II","civilwar":"Civil War","civilrights":"Civil Rights","ww1":"World War I","coldwar":"Cold War","westward":"Westward Expansion"};return(<div style={{display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",minHeight:"80vh",gap:14,padding:20,textAlign:"center",animation:"fadeIn 0.5s ease-out"}}><BB onClick={onBack}/>{battle.boss&&<div style={{fontFamily:fonts.heading,fontSize:"0.65rem",color:"#FF8A65"}}>⚠️ BOSS ⚠️</div>}<div style={{fontFamily:fonts.heading,fontSize:"0.5rem",letterSpacing:"0.15em",color:"#777",textTransform:"uppercase"}}>{eraLabels[era]||""}</div><div style={{fontFamily:fonts.heading,fontSize:"1.3rem",fontWeight:700,color:"#E0E0E0"}}>{battle.name}</div><div style={{fontFamily:fonts.body,fontSize:"0.85rem",color:"#999"}}>{battle.date}</div>{battle.context&&<div style={{background:"rgba(14,25,35,0.8)",border:"1px solid rgba(79,195,247,0.2)",borderRadius:10,padding:"10px 14px",maxWidth:400,boxShadow:"0 2px 6px rgba(0,0,0,0.25)"}}><div style={{fontFamily:fonts.heading,fontSize:"0.42rem",letterSpacing:"0.1em",color:"#4FC3F7",textTransform:"uppercase",marginBottom:3}}>📜 Context</div><div style={{fontFamily:fonts.body,fontSize:"0.8rem",color:"#CCC",lineHeight:1.45}}>{battle.context}</div></div>}
    {/* Enemy squad preview */}
    <div style={{background:"rgba(211,47,47,0.06)",border:"1px solid rgba(211,47,47,0.12)",borderRadius:10,padding:"10px 14px",maxWidth:380}}>
      <div style={{fontFamily:fonts.heading,fontSize:"0.42rem",letterSpacing:"0.1em",color:"#FF5252",textTransform:"uppercase",marginBottom:6}}>{{"revwar":"Enemy Forces","ww2":"Enemy Forces","civilwar":"Enemy Forces","civilrights":"Opposition","ww1":"Enemy Forces","coldwar":"Opposing Forces","westward":"Challenges"}[era||"revwar"]||"Enemy Forces"}</div>
      <div style={{display:"flex",gap:12,justifyContent:"center"}}>{battle.enemies.map((e,i)=>(<div key={i} style={{textAlign:"center"}}><span style={{fontSize:"1.2rem"}}>{e.icon}</span><div style={{fontFamily:fonts.heading,fontSize:"0.5rem",color:"#E0E0E0",marginTop:2}}>{e.name}</div><div style={{fontFamily:fonts.mono,fontSize:"0.45rem",color:"#999"}}>HP:{e.hp} ATK:{e.dmg}</div></div>))}</div>
    </div>
    {battle.boss&&<div style={{fontFamily:fonts.body,fontSize:"0.75rem",color:"#FF8A65",maxWidth:340}}>Phase 1: Review (reduced dmg) → Phase 2: Boss (full dmg). HP carries over!</div>}
    <div style={{background:difficulty==="normal"?"rgba(40,18,14,0.8)":"rgba(14,25,35,0.8)",border:`1px solid ${difficulty==="normal"?"rgba(239,83,80,0.25)":"rgba(79,195,247,0.25)"}`,borderRadius:10,padding:"8px 20px",cursor:"pointer",transition:"all 0.3s",boxShadow:"0 2px 8px rgba(0,0,0,0.3)"}} onClick={()=>onDiffChange(difficulty==="easy"?"normal":"easy")}><div style={{fontFamily:fonts.heading,fontSize:"0.4rem",letterSpacing:"0.15em",color:"#888",textTransform:"uppercase",textAlign:"center",marginBottom:2}}>Difficulty</div><div style={{fontFamily:fonts.heading,fontSize:"0.7rem",fontWeight:700,color:difficulty==="normal"?"#EF5350":"#4FC3F7",textAlign:"center"}}>{difficulty==="normal"?"NORMAL":"EASY"}</div></div>
    <button onClick={onStart} style={{...goldBtn,padding:"12px 44px",fontSize:"0.85rem"}}>Build Squad →</button>
  </div>);}
function ResultOvl({wasCorrect,question,selectedAnswer,damageResult,healAmt,onContinue}){return(<div style={{background:"linear-gradient(135deg,rgba(28,28,48,0.97),rgba(18,18,36,0.97))",borderRadius:11,padding:"14px 16px",border:`1px solid ${wasCorrect?"rgba(76,175,80,0.2)":"rgba(211,47,47,0.2)"}`,textAlign:"center"}}><div style={{fontFamily:fonts.heading,fontSize:"1.2rem",fontWeight:700,color:wasCorrect?"#66BB6A":"#EF5350",marginBottom:5}}>{wasCorrect?"CORRECT!":selectedAnswer===-1?"TIME'S UP!":"WRONG!"}</div>{wasCorrect&&damageResult&&<div style={{marginBottom:8}}><span style={{fontFamily:fonts.mono,fontSize:"1.4rem",color:damageResult.isCrit?"#FFD700":"#4FC3F7",fontWeight:700}}>{damageResult.damage}</span><span style={{fontFamily:fonts.body,fontSize:"0.75rem",color:"#999",marginLeft:4}}>dmg</span>{damageResult.isCrit&&<div style={{fontFamily:fonts.heading,fontSize:"0.55rem",color:"#FFD700",letterSpacing:"0.12em",marginTop:2}}>★ CRIT ★</div>}<div style={{fontFamily:fonts.mono,fontSize:"0.6rem",color:damageResult.tier.color,marginTop:2}}>{damageResult.tier.label} {damageResult.tier.multiplier}×</div>{healAmt>0&&<div style={{fontFamily:fonts.mono,fontSize:"0.6rem",color:"#66BB6A",marginTop:2}}>+{healAmt} HP healed</div>}</div>}{!wasCorrect&&<div style={{marginBottom:8}}><div style={{fontFamily:fonts.body,fontSize:"0.8rem",color:"#81C784",marginBottom:4}}>Answer: <strong>{question.options[question.answer]}</strong></div><div style={{background:"rgba(79,195,247,0.06)",border:"1px solid rgba(79,195,247,0.1)",borderRadius:7,padding:"6px 10px"}}><div style={{fontFamily:fonts.heading,fontSize:"0.4rem",letterSpacing:"0.1em",color:"#4FC3F7",textTransform:"uppercase",marginBottom:2}}>📝 Remember</div><div style={{fontFamily:fonts.body,fontSize:"0.75rem",color:"#CCC",lineHeight:1.4}}>{question.explanation}</div></div></div>}<button onClick={onContinue} style={blueBtn}>Continue</button></div>);}
function EnemyOvl({damage,name,onContinue}){return(<div style={{background:"linear-gradient(135deg,rgba(48,18,18,0.97),rgba(36,12,12,0.97))",borderRadius:11,padding:"14px 16px",border:"1px solid rgba(211,47,47,0.2)",textAlign:"center"}}><div style={{fontFamily:fonts.heading,fontSize:"0.95rem",fontWeight:700,color:"#EF5350",marginBottom:4}}>ENEMY ATTACKS!</div><div style={{fontFamily:fonts.body,fontSize:"0.82rem",color:"#E0E0E0",marginBottom:4}}>{name} strikes!</div><span style={{fontFamily:fonts.mono,fontSize:"1.4rem",color:"#EF5350",fontWeight:700}}>-{damage}</span><span style={{fontFamily:fonts.body,fontSize:"0.75rem",color:"#999",marginLeft:4}}>HP</span><div style={{marginTop:10}}><button onClick={onContinue} style={blueBtn}>Continue</button></div></div>);}
function FallenOvl({msg,onContinue}){return(<div style={{background:"linear-gradient(135deg,rgba(28,28,48,0.97),rgba(18,18,36,0.97))",borderRadius:11,padding:"16px 18px",border:"1px solid rgba(255,215,0,0.2)",textAlign:"center"}}><div style={{fontFamily:fonts.heading,fontSize:"1rem",fontWeight:700,color:"#FFD700",marginBottom:8}}>⚔️ UNIT DOWN ⚔️</div><div style={{fontFamily:fonts.body,fontSize:"0.9rem",color:"#E0E0E0",lineHeight:1.4,marginBottom:12}}>{msg}</div><button onClick={onContinue} style={blueBtn}>Continue</button></div>);}
function VScreen({state,battle,onRestart,onMenu,onShop}){const confettiColors=["#FFD700","#4FC3F7","#EF5350","#66BB6A","#CE93D8","#FFB74D","#FF8A65"];return(<div style={{display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",minHeight:"80vh",gap:14,padding:24,textAlign:"center",animation:"fadeIn 0.8s ease-out",position:"relative",overflow:"hidden"}}>{Array.from({length:30}).map((_,i)=><div key={i} style={{position:"absolute",top:0,left:`${(i/30)*100}%`,width:i%3===0?8:6,height:i%3===0?8:12,borderRadius:i%2===0?"50%":"2px",background:confettiColors[i%confettiColors.length],animation:`confettiFall ${2+Math.random()*2}s ease-in ${Math.random()*1.5}s forwards, confettiSway ${1+Math.random()}s ease-in-out ${Math.random()}s infinite`,opacity:0.9,pointerEvents:"none",zIndex:0}}/>)}<div style={{position:"relative",zIndex:1,display:"flex",flexDirection:"column",alignItems:"center",gap:14}}><div style={{fontFamily:fonts.heading,fontSize:"2rem",fontWeight:700,color:"#FFD700"}}>VICTORY</div><div style={{fontSize:"2rem",letterSpacing:"0.2em",color:"#FFD700"}}>{"★".repeat(state.stars)+"☆".repeat(3-state.stars)}</div><div style={{fontFamily:fonts.body,fontSize:"1rem",color:"#E0E0E0"}}>{battle.general.startsWith("the ")?"Overcame "+battle.general:battle.general+" defeated!"}</div><div style={{background:"rgba(20,18,14,0.8)",borderRadius:10,padding:"12px 24px",border:"1px solid rgba(255,215,0,0.15)",boxShadow:"0 2px 8px rgba(0,0,0,0.3)"}}><div style={{display:"flex",gap:22,justifyContent:"center"}}><div><div style={{fontFamily:fonts.mono,fontSize:"1.2rem",color:"#4FC3F7",fontWeight:700}}>{state.questionsCorrect}/{state.questionsAnswered}</div><div style={{fontFamily:fonts.body,fontSize:"0.6rem",color:"#999"}}>Correct</div></div><div><div style={{fontFamily:fonts.mono,fontSize:"1.2rem",color:"#FFD700",fontWeight:700}}>🪙 {state.coinsEarned}</div><div style={{fontFamily:fonts.body,fontSize:"0.6rem",color:"#999"}}>Coins{state.difficulty==="normal"?" (×1.5 bonus)":""}</div></div></div></div><div style={{display:"flex",gap:8}}><button onClick={onRestart} style={goldBtn}>Again</button><button onClick={onShop} style={{...btn("linear-gradient(135deg,#2E7D32,#1B5E20)","rgba(129,199,132,0.3)"),color:"#E0E0E0",fontWeight:700}}>Shop</button><button onClick={onMenu} style={blueBtn}>Map</button></div></div></div>);}
function DScreen({state,battle,onRestart,onMenu}){return(<div style={{display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",minHeight:"80vh",gap:14,padding:24,textAlign:"center",animation:"fadeIn 0.8s ease-out"}}><div style={{fontFamily:fonts.heading,fontSize:"2rem",fontWeight:700,color:"#EF5350"}}>DEFEAT</div><div style={{fontSize:"2rem"}}>💀</div><div style={{fontFamily:fonts.body,fontSize:"1rem",color:"#E0E0E0"}}>{battle.general.startsWith("the ")?"Lost to "+battle.general+".":"Fell to "+battle.general+"."}</div><div style={{fontFamily:fonts.body,fontSize:"0.85rem",color:"#999"}}>{state.questionsCorrect}/{state.questionsAnswered} correct</div><div style={{display:"flex",gap:8}}><button onClick={onRestart} style={redBtn}>Retry</button><button onClick={onMenu} style={blueBtn}>Map</button></div></div>);}

// ═════════════════════════════════════════════════════════════════════════════
// MAIN APP
// ═════════════════════════════════════════════════════════════════════════════
export default function HistoryLegends(){
  const[user,setUser]=useState(null);const[authLd,setAL]=useState(true);
  const[screen,setScreen]=useState(SCREENS.HOME);
  const[state,dispatch]=useReducer(gameReducer,{phase:"IDLE"});
  const[coins,setCoins]=useState(0);
  const[upgrades,setUpgrades]=useState({maxHP:0,baseDmg:0,critRate:0});
  const[completed,setCompleted]=useState([]);
  const[wrongAll,setWA]=useState([]);
  const[unlockedUnits,setUU]=useState(["infantry"]);
  const[difficulty,setDiff]=useState("easy");
  const[curBattle,setCB]=useState(BATTLES[0]);
  const[curSquad,setCS]=useState([]);
  const[curEra,setEra]=useState("revwar");
  const[dLoaded,setDL]=useState(false);
  const eR=useRef(0);const sT=useRef(null);

  const pStats={maxHP:UPGRADES.maxHP.levels[upgrades.maxHP],baseDmg:UPGRADES.baseDmg.levels[upgrades.baseDmg],critRate:UPGRADES.critRate.levels[upgrades.critRate]};

  useEffect(()=>{const u=onAuthStateChanged(auth,u=>{setUser(u);setAL(false);});return u;},[]);
  useEffect(()=>{if(!user){setDL(false);return;}(async()=>{const d=await loadUD(user.uid);if(d){setCoins(d.coins||0);setUpgrades(d.upgrades||{maxHP:0,baseDmg:0,critRate:0});setCompleted(d.completed||[]);setWA((d.wrongAnswers||[]).filter(q=>q?.text));setUU(d.unlockedUnits||["infantry"]);}setDL(true);})();},[user]);
  const saveFS=useCallback(()=>{if(!user||!dLoaded)return;if(sT.current)clearTimeout(sT.current);sT.current=setTimeout(()=>{saveUD(user.uid,{coins,upgrades,completed,wrongAnswers:wrongAll.map(q=>({text:q.text,options:q.options,answer:q.answer,explanation:q.explanation})),unlockedUnits,displayName:user.displayName||"Commander",lastSaved:new Date().toISOString()});},1000);},[user,dLoaded,coins,upgrades,completed,wrongAll,unlockedUnits]);
  useEffect(()=>{saveFS();},[coins,upgrades,completed,wrongAll,unlockedUnits]);

  const hAns=useCallback(i=>{if(state.phase!==PHASES.PLAYER_TURN)return;dispatch({type:"ANSWER",idx:i,elapsed:eR.current});},[state.phase]);
  const hTO=useCallback(()=>{if(state.phase!==PHASES.PLAYER_TURN)return;dispatch({type:"TIMEOUT"});},[state.phase]);
  const hTick=useCallback(p=>{eR.current=p;},[]);

  useEffect(()=>{if(state.phase===PHASES.ENEMY_TURN&&!state.enemyDamageResult){const t=setTimeout(()=>dispatch({type:"ENEMY_ATK"}),600);return()=>clearTimeout(t);}},[state.phase,state.enemyDamageResult]);
  useEffect(()=>{if(state.shakeEnemy||state.shakePlayer){const t=setTimeout(()=>dispatch({type:"CLEAR"}),500);return()=>clearTimeout(t);}},[state.shakeEnemy,state.shakePlayer]);
  useEffect(()=>{
    if(state.phase===PHASES.VICTORY&&state.coinsEarned>0){setCoins(c=>c+state.coinsEarned);if(!completed.includes(curBattle.id))setCompleted(c=>[...c,curBattle.id]);}
    if((state.phase===PHASES.VICTORY||state.phase===PHASES.DEFEAT)&&state.wrongThisBattle?.length>0){setWA(p=>{const n=[...p];state.wrongThisBattle.forEach(q=>{if(q&&!n.find(w=>w.text===q.text))n.push(q);});return n;});}
  },[state.phase]);

  const startBattle=(battle,squad)=>{
    let rv=null;
    if(battle.boss){const allB={"ww2":WW2_BATTLES,"civilwar":CW_BATTLES,"civilrights":CR_BATTLES,"ww1":WWI_BATTLES,"coldwar":CW2_BATTLES,"westward":WE_BATTLES}[curEra]||BATTLES;const eraQTexts=new Set(allB.flatMap(b=>b.questions.map(q=>q.text)));const wQ=wrongAll.filter(q=>q&&eraQTexts.has(q.text)&&!battle.questions.find(b=>b.text===q.text));const pB=allB.filter(b=>b.id!==battle.id&&!b.boss);const pQs=pB.flatMap(b=>b.questions);const nW=pQs.filter(q=>!wQ.find(w=>w.text===q.text));rv=[...wQ,...shuffleArray(nW).slice(0,Math.max(0,6-wQ.length))].slice(0,8);}
    setCS(squad);dispatch({type:"START",battle,squad:squad.map(u=>({...u,name:u.eraNames?.[curEra]||u.name})),playerStats:pStats,reviewQs:rv,difficulty});setScreen(SCREENS.BATTLE);
  };
  const goMap=()=>{const m={"ww2":SCREENS.WW2,"civilwar":SCREENS.CIVIL_WAR,"civilrights":SCREENS.CIVIL_RIGHTS,"ww1":SCREENS.WWI,"coldwar":SCREENS.COLD_WAR,"westward":SCREENS.WESTWARD};setScreen(m[curEra]||SCREENS.REV_WAR);};
  const goMenu=()=>setScreen(SCREENS.HOME);
  const logout=async()=>{await signOut(auth);setCoins(0);setUpgrades({maxHP:0,baseDmg:0,critRate:0});setCompleted([]);setWA([]);setUU(["infantry"]);};
  const buyUpg=k=>{const u=UPGRADES[k],lv=upgrades[k];if(lv>=u.levels.length-1)return;const c=u.costs[lv+1];if(coins<c)return;setCoins(v=>v-c);setUpgrades(v=>({...v,[k]:v[k]+1}));};
  const unlockU=u=>{if(coins<u.cost||unlockedUnits.includes(u.id))return;setCoins(c=>c-u.cost);setUU(v=>[...v,u.id]);};

  const pU=state.pSquad?activeUnit(state.pSquad):null;
  const eU=state.eSquad?activeUnit(state.eSquad):null;
  const ps=pU?getCS(pU.hp,pU.maxHP,state.phase,true,state.wasCorrect,!!state.enemyDamageResult):"idle";
  const es=eU?getCS(eU.hp,eU.maxHP,state.phase,false,state.wasCorrect,!!state.enemyDamageResult):"idle";

  if(authLd)return(<div style={{minHeight:"100vh",backgroundColor:"#1a1510",backgroundImage:"url(/bg/leather-tile.jpg)",backgroundSize:"512px 512px",backgroundRepeat:"repeat",display:"flex",alignItems:"center",justifyContent:"center"}}><div style={{fontFamily:fonts.heading,color:"#FFD700",animation:"pulse 1s infinite"}}>Loading...</div></div>);
  if(!user)return<AuthScreen/>;
  if(!dLoaded)return(<div style={{minHeight:"100vh",backgroundColor:"#1a1510",backgroundImage:"url(/bg/leather-tile.jpg)",backgroundSize:"512px 512px",backgroundRepeat:"repeat",display:"flex",alignItems:"center",justifyContent:"center"}}><div style={{fontFamily:fonts.heading,color:"#4FC3F7",animation:"pulse 1s infinite"}}>Loading save...</div></div>);

  return(
    <div style={{minHeight:"100vh",backgroundColor:"#1a1510",backgroundImage:"url(/bg/leather-tile.jpg)",backgroundSize:"512px 512px",backgroundRepeat:"repeat",color:"#E0E0E0",fontFamily:fonts.body,position:"relative",overflow:"hidden"}}>
      <div style={{position:"absolute",inset:0,backgroundImage:"radial-gradient(circle at 20% 30%,rgba(79,195,247,0.03) 0%,transparent 50%),radial-gradient(circle at 80% 70%,rgba(198,40,40,0.03) 0%,transparent 50%)",pointerEvents:"none"}}/>
      <div style={{maxWidth:600,margin:"0 auto",padding:16,position:"relative",zIndex:1,minHeight:"100vh",display:"flex",flexDirection:"column"}}>
        {screen!==SCREENS.BATTLE&&screen!==SCREENS.HOME&&screen!==SCREENS.AUTH&&screen!==SCREENS.REV_WAR&&screen!==SCREENS.WW2&&screen!==SCREENS.CIVIL_WAR&&screen!==SCREENS.CIVIL_RIGHTS&&screen!==SCREENS.WWI&&screen!==SCREENS.COLD_WAR&&screen!==SCREENS.WESTWARD&&<div style={{textAlign:"center",padding:"6px 0 8px",borderBottom:"1px solid rgba(255,255,255,0.04)",marginBottom:12}}><img src="/logo.png" alt="History Legends" style={{width:100,height:"auto",cursor:"pointer",filter:"drop-shadow(0 2px 6px rgba(255,215,0,0.15))"}} onClick={goMenu}/></div>}
        {screen!==SCREENS.BATTLE&&screen!==SCREENS.SHOP&&<ShopBtn onClick={()=>setScreen(SCREENS.SHOP)} coins={coins}/>}
        <div style={{flex:1}}>
          {screen===SCREENS.SPRITE_GALLERY&&<SpriteGalleryScreen onBack={()=>setScreen(SCREENS.HOME)}/>}
          {screen===SCREENS.HOME&&<HomeScreen onNav={setScreen} coins={coins} userName={user.displayName||"Commander"} onLogout={logout}/>}
          {screen===SCREENS.US_HISTORY&&<USScreen onNav={setScreen} onBack={()=>setScreen(SCREENS.HOME)} completed={completed}/>}
          {screen===SCREENS.REV_WAR&&<MapScreen onBack={()=>setScreen(SCREENS.US_HISTORY)} onSelect={b=>{setCB(b);setEra("revwar");setScreen(SCREENS.PRE_BATTLE);}} completed={completed} mapData={REV_WAR_MAP} battles={BATTLES} title="Revolutionary War"/>}
          {screen===SCREENS.WW2&&<MapScreen onBack={()=>setScreen(SCREENS.US_HISTORY)} onSelect={b=>{setCB(b);setEra("ww2");setScreen(SCREENS.PRE_BATTLE);}} completed={completed} mapData={WW2_MAP} battles={WW2_BATTLES} title="World War II"/>}
          {screen===SCREENS.CIVIL_WAR&&<MapScreen onBack={()=>setScreen(SCREENS.US_HISTORY)} onSelect={b=>{setCB(b);setEra("civilwar");setScreen(SCREENS.PRE_BATTLE);}} completed={completed} mapData={CW_MAP} battles={CW_BATTLES} title="Civil War"/>}
          {screen===SCREENS.CIVIL_RIGHTS&&<MapScreen onBack={()=>setScreen(SCREENS.US_HISTORY)} onSelect={b=>{setCB(b);setEra("civilrights");setScreen(SCREENS.PRE_BATTLE);}} completed={completed} mapData={CR_MAP} battles={CR_BATTLES} title="Civil Rights Movement"/>}
          {screen===SCREENS.WWI&&<MapScreen onBack={()=>setScreen(SCREENS.US_HISTORY)} onSelect={b=>{setCB(b);setEra("ww1");setScreen(SCREENS.PRE_BATTLE);}} completed={completed} mapData={WWI_MAP} battles={WWI_BATTLES} title="World War I"/>}
          {screen===SCREENS.COLD_WAR&&<MapScreen onBack={()=>setScreen(SCREENS.US_HISTORY)} onSelect={b=>{setCB(b);setEra("coldwar");setScreen(SCREENS.PRE_BATTLE);}} completed={completed} mapData={CW2_MAP} battles={CW2_BATTLES} title="Cold War"/>}
          {screen===SCREENS.WESTWARD&&<MapScreen onBack={()=>setScreen(SCREENS.US_HISTORY)} onSelect={b=>{setCB(b);setEra("westward");setScreen(SCREENS.PRE_BATTLE);}} completed={completed} mapData={WE_MAP} battles={WE_BATTLES} title="Westward Expansion"/>}
          {screen===SCREENS.SHOP&&<ShopScreen onBack={()=>setScreen(SCREENS.HOME)} coins={coins} upgrades={upgrades} onBuy={buyUpg}/>}
          {screen===SCREENS.PRE_BATTLE&&<PreBattle battle={curBattle} era={curEra} onStart={()=>setScreen(SCREENS.UNIT_SELECT)} onBack={goMap} difficulty={difficulty} onDiffChange={setDiff}/>}
          {screen===SCREENS.UNIT_SELECT&&<UnitSelectScreen battle={curBattle} era={curEra} unlockedUnits={unlockedUnits} coins={coins} onUnlock={unlockU} onGo={sq=>startBattle(curBattle,sq)} onBack={()=>setScreen(SCREENS.PRE_BATTLE)}/>}

          {screen===SCREENS.BATTLE&&<>
            {state.phase===PHASES.VICTORY&&<VScreen state={state} battle={curBattle} onRestart={()=>setScreen(SCREENS.UNIT_SELECT)} onMenu={goMap} onShop={()=>setScreen(SCREENS.SHOP)}/>}
            {state.phase===PHASES.DEFEAT&&<DScreen state={state} battle={curBattle} onRestart={()=>setScreen(SCREENS.UNIT_SELECT)} onMenu={goMap}/>}
            {state.phase!==PHASES.VICTORY&&state.phase!==PHASES.DEFEAT&&state.pSquad&&state.eSquad&&<>
              {/* Header */}
              <div style={{position:"relative",textAlign:"center",padding:"3px 0 5px",flexShrink:0}}>
                <button onClick={goMap} style={{position:"absolute",left:8,top:2,background:"rgba(20,18,14,0.7)",border:"1px solid rgba(255,255,255,0.1)",borderRadius:8,padding:"4px 10px",cursor:"pointer",fontFamily:fonts.heading,fontSize:"0.45rem",color:"#999",letterSpacing:"0.1em"}}>✕ QUIT</button>
                <div style={{fontFamily:fonts.heading,fontSize:"0.42rem",letterSpacing:"0.18em",color:"#555",textTransform:"uppercase"}}>{{"revwar":"Revolutionary War","ww2":"World War II","civilwar":"Civil War","civilrights":"Civil Rights","ww1":"World War I","coldwar":"Cold War","westward":"Westward Expansion"}[curEra]||curEra}{state.difficulty==="normal"?" · NORMAL":""}</div><div style={{fontFamily:fonts.heading,fontSize:"0.58rem",fontWeight:700,color:"#9E9E9E",marginTop:1}}>{curBattle.name} · {state.questionsCorrect}/{state.questionsAnswered}</div>
                {state.bossPhase&&<div style={{fontFamily:fonts.heading,fontSize:"0.48rem",marginTop:2,padding:"2px 10px",borderRadius:5,display:"inline-block",background:state.bossPhase==="review"?"rgba(79,195,247,0.1)":"rgba(255,138,101,0.1)",color:state.bossPhase==="review"?"#4FC3F7":"#FF8A65"}}>{state.bossPhase==="review"?"📖 REVIEW":"⚔️ BOSS"}</div>}
              </div>

              {/* ═══ 3v3 BATTLEFIELD ═══ */}
              {(()=>{const pacificIds=["pearlharbor","midway","iwojima","okinawa"];const winterIds=["bulge"];const roomIds=["cuban"];const bgSrc=curEra==="ww2"?(pacificIds.includes(curBattle.id)?"/bg/ww2-pacific.jpg":winterIds.includes(curBattle.id)?"/bg/ww2-winter.jpg":"/bg/ww2-europe.jpg"):curEra==="civilwar"?"/bg/civilwar.jpg":curEra==="civilrights"?"/bg/civilrights.jpg":curEra==="ww1"?"/bg/ww1.jpg":curEra==="coldwar"?(roomIds.includes(curBattle.id)?"/bg/coldwar-room.jpg":"/bg/coldwar.jpg"):curEra==="westward"?"/bg/westward.jpg":"/bg/revwar.jpg";return(
              <div style={{position:"relative",width:"100%",height:290,borderRadius:14,overflow:"hidden",marginBottom:8,flexShrink:0,border:"1px solid rgba(255,255,255,0.06)"}}>
                <div style={{position:"absolute",inset:0,backgroundImage:`url(${bgSrc})`,backgroundSize:"cover",backgroundPosition:"center center"}}/>
                <div style={{position:"absolute",inset:0,background:"linear-gradient(180deg,transparent 0%,transparent 60%,rgba(0,0,0,0.15) 100%)"}}/>

                {/* Player squad (left side) — 3 units staggered */}
                <div style={{position:"absolute",bottom:"8%",left:"2%",display:"flex",gap:2,alignItems:"flex-end",zIndex:2,animation:state.shakePlayer?"shakeHit 0.4s ease-out":"none"}}>
                  {state.pSquad.map((u,i)=>{
                    const isActive=!u.fallen&&state.pSquad.findIndex(x=>!x.fallen)===i;
                    const sz=isActive?95:45;
                    const uState=isActive?ps:"idle";
                    return(<div key={`p${i}`} style={{display:"flex",flexDirection:"column",alignItems:"center",opacity:u.fallen?0.35:1,filter:u.fallen?"grayscale(1)":"none",transition:"all 0.3s",marginBottom:isActive?0:-5,zIndex:isActive?3:1}}>
                      {/* Mini HP bar */}
                      <div style={{width:sz-10,marginBottom:2}}>
                        <div style={{fontFamily:fonts.mono,fontSize:"0.35rem",color:u.fallen?"#888":u.color||"#42A5F5",textAlign:"center",textShadow:"0 1px 2px rgba(0,0,0,0.6)",marginBottom:1}}>{u.icon}{isActive?" ▶":""}</div>
                        <div style={{background:"rgba(0,0,0,0.6)",borderRadius:3,height:10,overflow:"hidden",border:`1px solid ${u.fallen?"#55555544":"rgba(66,165,245,0.3)"}`,position:"relative"}}>
                          <div style={{width:`${u.maxHP>0?Math.max(0,(u.hp/u.maxHP)*100):0}%`,height:"100%",background:u.fallen?"#555":`linear-gradient(90deg,${u.hp/u.maxHP>0.5?"#1565C0":"#D32F2F"},#42A5F5)`,borderRadius:2,transition:"width 0.5s"}}/>
                          <div style={{position:"absolute",inset:0,display:"flex",alignItems:"center",justifyContent:"center",fontFamily:fonts.mono,fontSize:"0.38rem",color:"#fff",textShadow:"0 1px 2px rgba(0,0,0,0.8)",fontWeight:700}}>{u.fallen?"☠":u.hp}</div>
                        </div>
                      </div>
                      <div style={{filter:isActive?"drop-shadow(2px 3px 5px rgba(0,0,0,0.4))":"drop-shadow(1px 2px 3px rgba(0,0,0,0.3))"}}><EraPlayerSprite era={curEra} state={u.fallen?"critical":uState} size={sz}/></div>
                      {u.fallen&&<div style={{position:"absolute",top:"40%",fontSize:"1.2rem"}}>💀</div>}
                    </div>);
                  })}
                </div>

                {/* Enemy squad (right side) — 3 units staggered */}
                <div style={{position:"absolute",bottom:"4%",right:"2%",display:"flex",flexDirection:"row-reverse",gap:2,alignItems:"flex-end",zIndex:2,animation:state.shakeEnemy?"shakeHit 0.4s ease-out":"none"}}>
                  {state.eSquad.map((u,i)=>{
                    const isActive=!u.fallen&&state.eSquad.findIndex(x=>!x.fallen)===i;
                    const sz=isActive?95:45;
                    const uState=isActive?es:"idle";
                    return(<div key={`e${i}`} style={{display:"flex",flexDirection:"column",alignItems:"center",opacity:u.fallen?0.35:1,filter:u.fallen?"grayscale(1)":"none",transition:"all 0.3s",marginBottom:isActive?0:-5,zIndex:isActive?3:1}}>
                      <div style={{width:sz-10,marginBottom:2}}>
                        <div style={{fontFamily:fonts.mono,fontSize:"0.35rem",color:u.fallen?"#888":"#FF5252",textAlign:"center",textShadow:"0 1px 2px rgba(0,0,0,0.6)",marginBottom:1}}>{u.icon}{isActive?" ▶":""}</div>
                        <div style={{background:"rgba(0,0,0,0.6)",borderRadius:3,height:10,overflow:"hidden",border:`1px solid ${u.fallen?"#55555544":"rgba(255,82,82,0.3)"}`,position:"relative"}}>
                          <div style={{width:`${u.maxHP>0?Math.max(0,(u.hp/u.maxHP)*100):0}%`,height:"100%",background:u.fallen?"#555":`linear-gradient(90deg,${u.hp/u.maxHP>0.5?"#C62828":"#D32F2F"},#FF5252)`,borderRadius:2,transition:"width 0.5s"}}/>
                          <div style={{position:"absolute",inset:0,display:"flex",alignItems:"center",justifyContent:"center",fontFamily:fonts.mono,fontSize:"0.38rem",color:"#fff",textShadow:"0 1px 2px rgba(0,0,0,0.8)",fontWeight:700}}>{u.fallen?"☠":u.hp}</div>
                        </div>
                      </div>
                      <div style={{filter:isActive?"drop-shadow(2px 3px 5px rgba(0,0,0,0.4))":"drop-shadow(1px 2px 3px rgba(0,0,0,0.3))",transform:"scaleX(-1)"}}><EraEnemySprite era={curEra} state={u.fallen?"critical":uState} size={sz}/></div>
                      {u.fallen&&<div style={{position:"absolute",top:"40%",fontSize:"1.2rem"}}>💀</div>}
                    </div>);
                  })}
                </div>

                {/* Damage floaters */}
                {state.phase==="ANSWER_RESULT"&&state.wasCorrect&&state.damageResult&&(<div style={{position:"absolute",top:"15%",right:"25%",zIndex:5,animation:"floatUp 1s ease-out",pointerEvents:"none"}}><span style={{fontFamily:fonts.mono,fontSize:state.damageResult.isCrit?"1.5rem":"1.1rem",fontWeight:700,color:state.damageResult.isCrit?"#FFD700":"#4FC3F7",textShadow:"0 2px 8px rgba(0,0,0,0.8)"}}>-{state.damageResult.damage}</span></div>)}
                {state.phase==="ENEMY_TURN"&&state.enemyDamageResult&&(<div style={{position:"absolute",top:"15%",left:"18%",zIndex:5,animation:"floatUp 1s ease-out",pointerEvents:"none"}}><span style={{fontFamily:fonts.mono,fontSize:"1.1rem",fontWeight:700,color:"#EF5350",textShadow:"0 2px 8px rgba(0,0,0,0.8)"}}>-{state.enemyDamageResult}</span></div>)}
              </div>)})()}

              {/* ═══ QUESTION UI ═══ */}
              <div style={{flex:1,display:"flex",flexDirection:"column",gap:8,minHeight:0,overflowY:"auto"}}>
                {state.phase===PHASES.PLAYER_TURN&&state.currentQuestion&&<><Timer duration={TIMER_DURATION} onTimeout={hTO} isActive={true} onTick={hTick}/><QCard question={state.currentQuestion} onAnswer={hAns} disabled={false}/></>}
                {state.phase===PHASES.ANSWER_RESULT&&state.currentQuestion&&<ResultOvl wasCorrect={state.wasCorrect} question={state.currentQuestion} selectedAnswer={state.selectedAnswer} damageResult={state.damageResult} healAmt={state.wasCorrect&&pU?.special==="heal"?(pU.healAmt||8):0} onContinue={()=>dispatch({type:"PROCEED"})}/>}
                {state.phase===PHASES.UNIT_FALLEN&&<FallenOvl msg={state.fallenMsg} onContinue={()=>dispatch({type:"DISMISS_FALLEN"})}/>}
                {state.phase===PHASES.ENEMY_TURN&&state.enemyDamageResult&&<EnemyOvl damage={state.enemyDamageResult} name={eU?eU.name:curBattle.general} onContinue={()=>dispatch({type:"AFTER_ENEMY"})}/>}
                {state.phase===PHASES.ENEMY_TURN&&!state.enemyDamageResult&&<div style={{textAlign:"center",padding:16,fontFamily:fonts.heading,fontSize:"0.85rem",color:"#EF5350",animation:"pulse 0.8s infinite"}}>Enemy attacking...</div>}
                <div style={{marginTop:"auto",paddingTop:4}}><BLog log={state.turnLog}/></div>
              </div>
            </>}
          </>}
        </div>
      </div>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Cinzel:wght@400;700;900&family=EB+Garamond:ital,wght@0,400;0,600;1,400&family=Share+Tech+Mono&display=swap');
        @keyframes shakeHit{0%,100%{transform:translateX(0)}20%{transform:translateX(-8px)}40%{transform:translateX(8px)}60%{transform:translateX(-4px)}80%{transform:translateX(4px)}}
        @keyframes pulse{0%,100%{opacity:1}50%{opacity:0.4}}
        @keyframes fadeIn{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:translateY(0)}}
        @keyframes floatUp{from{opacity:1;transform:translateY(0)}to{opacity:0;transform:translateY(-35px)}}
        @keyframes idleBob{0%,100%{transform:scaleY(1)}50%{transform:scaleY(1.015)}}
        @keyframes confettiFall{0%{transform:translateY(-10vh) rotate(0deg);opacity:1}80%{opacity:1}100%{transform:translateY(100vh) rotate(720deg);opacity:0}}
        @keyframes confettiSway{0%,100%{margin-left:0}25%{margin-left:15px}75%{margin-left:-15px}}
        *{box-sizing:border-box;margin:0;padding:0}
        ::-webkit-scrollbar{width:3px}::-webkit-scrollbar-track{background:transparent}::-webkit-scrollbar-thumb{background:rgba(255,255,255,0.08);border-radius:2px}
        button:hover{filter:brightness(1.08);transform:translateY(-1px)}button:active{transform:translateY(0)}
        input:focus{border-color:rgba(79,195,247,0.5)!important;box-shadow:0 0 8px rgba(79,195,247,0.15)}
      `}</style>
    </div>
  );
}
